class Solution:
    def equalScoreSubstrings(self, s: str) -> bool:
        n = len(s)
        for i in range(n - 1):
            if sum(ord(c) - 96 for c in s[:i+1]) == sum(ord(c) - 96 for c in s[i+1:]):
                return True
        return False

