class Solution {
public:
    bool equalScoreSubstrings(string s) {
        int n = s.size();
        for (int i = 0; i + 1 < n; i++) {
            int l = 0, r = 0;
            for (int j = 0; j <= i; j++) l += s[j] - 'a' + 1;
            for (int j = i + 1; j < n; j++) r += s[j] - 'a' + 1;
            if (l == r) return true;
        }
        return false;
    }
};

